use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn build_tree(pre:Vec<i32>,ino:Vec<i32>)->Option<Rc<RefCell<TreeNode>>>{fn f(pre:&[i32],idx:&mut usize,ino:&[i32],l:i32,r:i32)->Option<Rc<RefCell<TreeNode>>>{if l>r{return None}let v=pre[*idx];*idx+=1;let mut k=l;while ino[k as usize]!=v{k+=1}Some(Rc::new(RefCell::new(TreeNode{val:v,left:f(pre,idx,ino,l,k-1),right:f(pre,idx,ino,k+1,r)})))}let mut i=0;f(&pre,&mut i,&ino,0,ino.len()as i32-1)}}
